examples.template:
VStack(spacing: 0) {
    if !isDismissed {
        let message = Text({{message}})
            .monarchTextStyle(.bodySmall)
            .foregroundStyle(theme.colors.textDefault)
            .fixedSize(horizontal: false, vertical: true)
        let link = Button {
            if let url = URL(string: "https://example.com/releases") { openURL(url) }
        } label: {
            HStack(spacing: theme.spacing.space1) {
                Text({{action.label}})
                    .underline()
                MonarchIcon(systemName: "arrow.right", size: .sm)
            }
            .monarchTextStyle(.bodySmall, weight: .semibold)
            .foregroundStyle(theme.colors.textDefault)
            .frame(minHeight: 44)
        }
        .buttonStyle(.plain)
        let close = Button {
            isDismissed = true
        } label: {
            MonarchIcon(systemName: "xmark", label: "Dismiss", size: .sm)
                .foregroundStyle(theme.colors.textDefault)
                .monarchMinimumHitTarget()
        }
        .buttonStyle(.plain)
        ViewThatFits(in: .horizontal) {
            HStack(spacing: theme.spacing.space3) {
                Spacer(minLength: 0)
                message
                link
                close
                Spacer(minLength: 0)
            }
            HStack(alignment: .top, spacing: theme.spacing.space3) {
                VStack(alignment: .leading, spacing: 0) {
                    message.padding(.top, theme.spacing.space3)
                    link
                }
                Spacer(minLength: 0)
                close
            }
        }
        .padding(.horizontal, theme.spacing.space4)
        .background(theme.colors.accentSubtle)
        .overlay(alignment: .bottom) {
            Rectangle().fill(theme.colors.accentBorder).frame(height: 1)
        }
    }
}

